#include "../SharedRecordingGate.h"
#include <stdexcept>
#include <iostream>
int main(){using studio::opal::SharedRecordingGate;try{SharedRecordingGate gate;auto first=gate.Select("window:selected-fixture");if(gate.CanRecord("window:selected-fixture"))throw std::runtime_error("Unacknowledged sharing must reject recording without opening capture");gate.Confirm(first,true);if(!gate.CanRecord("window:selected-fixture")||gate.CanRecord("monitor:whole-PC"))throw std::runtime_error("Recording must match the confirmed source exactly");auto second=gate.Select("window:another-fixture");if(gate.Confirm(first,true)||gate.CanRecord("window:another-fixture"))throw std::runtime_error("Old outgoing acknowledgment must not confirm a replacement source");gate.Confirm(second,true);gate.Confirm(second,false);if(gate.CanRecord("window:another-fixture"))throw std::runtime_error("Failed outgoing encoding must revoke recording eligibility");gate.Select("");if(gate.CanRecord("window:selected-fixture"))throw std::runtime_error("Stopped sharing must reject recording");std::cout<<"Confirmed selected-share recording gate PASS\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
